CREATE OR REPLACE FUNCTION public.staff_case_members() RETURNS TABLE(user_id uuid,full_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_enabled(auth.uid()) OR NOT is_staff(auth.uid()) THEN RAISE EXCEPTION 'Staff access required'; END IF; RETURN QUERY SELECT DISTINCT u.user_id,p.full_name FROM user_roles u LEFT JOIN profiles p ON p.id=u.user_id WHERE staff_enabled(u.user_id) AND u.role IN ('admin','ops_manager','dispatcher','finance','partner_manager','rider_supervisor','support') AND (u.user_id=auth.uid() OR staff_nationwide() OR EXISTS(SELECT 1 FROM staff_scopes a JOIN staff_scopes b ON b.city_id=a.city_id WHERE a.user_id=auth.uid() AND b.user_id=u.user_id)); END $$;
CREATE OR REPLACE FUNCTION public.staff_rider_payment_preview(_rider uuid,_from date,_to date) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE n numeric; BEGIN IF NOT staff_rider_allowed('finance',_rider) THEN RAISE EXCEPTION 'Rider finance scope denied'; END IF; SELECT coalesce(sum(amount),0) INTO n FROM rider_earnings WHERE rider_id=_rider AND status='pending' AND (created_at AT TIME ZONE 'Asia/Karachi')::date BETWEEN _from AND _to; RETURN n; END $$;
CREATE TABLE public.staff_bank_reconciliation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ledger_id uuid NOT NULL UNIQUE REFERENCES public.bank_ledger(id),statement_reference text NOT NULL,confirmed_amount numeric NOT NULL,statement_date date NOT NULL,reviewed_by uuid NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_bank_reconciliation TO authenticated; GRANT ALL ON public.staff_bank_reconciliation TO service_role; ALTER TABLE public.staff_bank_reconciliation ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Scoped bank confirmation read" ON public.staff_bank_reconciliation FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM bank_ledger b WHERE b.id=ledger_id));
CREATE OR REPLACE FUNCTION public.staff_confirm_bank_entry(_ledger uuid,_reference text,_amount numeric,_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bank_ledger; city uuid; c uuid; BEGIN SELECT * INTO b FROM bank_ledger WHERE id=_ledger FOR UPDATE; IF NOT FOUND OR NOT has_permission(auth.uid(),'finance') OR NOT (staff_nationwide() OR staff_rider_allowed('finance',b.counterparty_id) OR staff_vendor_allowed(b.counterparty_id)) THEN RAISE EXCEPTION 'Ledger scope denied'; END IF; IF b.created_by=auth.uid() THEN RAISE EXCEPTION 'Independent bank reviewer required'; END IF; IF length(trim(coalesce(_reference,'')))<3 OR _amount IS NULL OR _date IS NULL THEN RAISE EXCEPTION 'Bank statement evidence required'; END IF;
 IF _amount<>b.amount THEN SELECT city_id INTO city FROM riders WHERE id=b.counterparty_id; IF city IS NULL THEN SELECT city_id INTO city FROM restaurants WHERE owner_id=b.counterparty_id LIMIT 1; END IF; INSERT INTO staff_cases(source_kind,source_id,city_id,department,title,next_action) VALUES('bank_ledger',_ledger::text,city,'finance','بینک رقم میں فرق؛ تحقیق درکار','آزاد بینک اسٹیٹمنٹ سے فرق جانچیں') ON CONFLICT(source_kind,source_id) DO UPDATE SET status='open',next_action=excluded.next_action RETURNING id INTO c; INSERT INTO staff_case_events(case_id,actor_id,action,note) VALUES(c,auth.uid(),'bank_mismatch','رقم کا فرق: '||(_amount-b.amount)::text); ELSE INSERT INTO staff_bank_reconciliation(ledger_id,statement_reference,confirmed_amount,statement_date,reviewed_by) VALUES(_ledger,left(_reference,200),_amount,_date,auth.uid()); END IF; END $$;
CREATE OR REPLACE FUNCTION public.staff_cash_difference_case() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN IF coalesce(NEW.shortage_amount,0)<>0 OR coalesce(NEW.overage_amount,0)<>0 THEN SELECT city_id INTO c FROM riders WHERE id=NEW.rider_id; INSERT INTO staff_cases(source_kind,source_id,city_id,department,title,next_action) VALUES('cash_difference',NEW.id::text,c,'finance','نقد رقم میں فرق؛ تحقیق درکار','اصل وصولی اور نقد حساب کا آزاد جائزہ') ON CONFLICT(source_kind,source_id) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_cash_difference AFTER INSERT OR UPDATE OF shortage_amount,overage_amount ON public.rider_remittances FOR EACH ROW EXECUTE FUNCTION public.staff_cash_difference_case();
REVOKE ALL ON FUNCTION public.staff_case_members(),public.staff_rider_payment_preview(uuid,date,date),public.staff_confirm_bank_entry(uuid,text,numeric,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_case_members(),public.staff_rider_payment_preview(uuid,date,date),public.staff_confirm_bank_entry(uuid,text,numeric,date) TO authenticated,service_role; REVOKE ALL ON FUNCTION public.staff_cash_difference_case() FROM PUBLIC,anon,authenticated;